import { readEntitlements } from "@/lib/entitlements";
import { readBillingStatus } from "@/lib/billing/status";
import { gmailPauseMessage } from "@/lib/gmail-pause";
import { DateTime } from "@/components/date-time";
import { Suspense } from "react";
import { WorkspaceSkeleton } from "@/components/workspace-skeleton";
import { requireUser } from "@/lib/session";
import { db } from "@/lib/db";
import { signIn } from "@/auth";
import { SettingsNav } from "@/components/settings/SettingsNav";
import { OutreachPreferences } from "@/components/settings/OutreachPreferences";
import { PlanSummary } from "@/components/settings/PlanSummary";
import { GmailConnection } from "@/components/settings/GmailConnection";
import { ResumeUpload } from "@/components/settings/ResumeUpload";
import { FollowUpReminders } from "@/components/settings/FollowUpReminders";
import { YourData } from "@/components/settings/YourData";
import { DangerZone } from "@/components/settings/DangerZone";
import styles from "@/components/settings/settings.module.css";
import { hasBlobStorage } from "@/lib/storage";

export const metadata = { title: "Settings" };
async function SettingsContent() {
  const user = await requireUser();
  const attachment = user.currentAttachmentId
    ? await db.attachment.findFirst({
        where: { id: user.currentAttachmentId, userId: user.id },
        select: { fileName: true },
      })
    : null;
  const [access, billing] = await Promise.all([
    readEntitlements(user.id),
    readBillingStatus(user.id),
  ]);
  const connected = user.gmailAuthorized && !!user.encryptedRefreshToken;
  return (
    <>
      <OutreachPreferences roles={user.preferredRoles} />
      <PlanSummary billing={billing} />
      <div className="grid grid-cols-[repeat(2,_minmax(0,_1fr))] gap-5 items-start [@media(width_<_860px)]:grid-cols-[minmax(0,_1fr)]">
        <GmailConnection
          email={user.email}
          connected={connected}
          paused={!!access.gmailPause}
          pauseDetails={
            access.gmailPause && (
              <div role="status" className="mt-4 text-sm text-warning">
                <p>{gmailPauseMessage(access.gmailPause)}</p>
                {access.gmailPause.until && (
                  <p>
                    Provider cooldown until{" "}
                    <DateTime value={access.gmailPause.until} />.
                  </p>
                )}
              </div>
            )
          }
          reconnectAction={async () => {
            "use server";
            await requireUser();
            await signIn("google", { redirectTo: "/settings" });
          }}
        />
        <ResumeUpload
          userId={user.id}
          fileName={attachment?.fileName ?? null}
          useBlob={hasBlobStorage() || process.env.NODE_ENV === "production"}
          usePresignedBlob={
            !!process.env.BLOB_STORE_ID && !process.env.BLOB_READ_WRITE_TOKEN
          }
        />
      </div>
      <FollowUpReminders days={user.followUpDays} />
      <YourData />
      <DangerZone email={user.email} />
    </>
  );
}

export default function Settings() {
  return (
    <div className={`${styles.page} text-[var(--settings-text)] min-w-0`}>
      <header className={`workspace-screen-heading [margin:22px_0_32px]`}>
        <p
          className={`${styles.eyebrow} [font:500_11.5px_var(--font-jetbrains),_monospace] tracking-[0.14em] uppercase text-[var(--settings-purple)]`}
        >
          Ready for your next chapter
        </p>
        <h1 className="mt-2 text-[clamp(30px,4.6vw,46px)] leading-[1.08] font-extrabold tracking-[-0.04em]">
          Settings
        </h1>
        <p className="mt-2 text-[var(--settings-muted)]">
          Manage your subscription, Gmail connection, and PDF attachment.
        </p>
      </header>
      <div className="grid grid-cols-[190px_minmax(0,_1fr)] gap-9 items-start [@media(width_<_860px)]:grid-cols-[minmax(0,_1fr)] [@media(width_<_860px)]:gap-6">
        <SettingsNav />
        <div className="grid gap-5 min-w-0">
          <Suspense
            fallback={<WorkspaceSkeleton page="settings" heading={false} />}
          >
            <SettingsContent />
          </Suspense>
        </div>
      </div>
    </div>
  );
}
